import{_ as t,c as r,o as n,ae as a}from"./chunks/framework.Cd-3tpCq.js";const m=JSON.parse(`{"title":"Create Return","description":"","frontmatter":{"outline":false,"apiType":"rest","examples":[{"id":"admin-create-return","title":"Create Return","description":"Open a return (or item cancellation) for any customer order. rma_qty is capped server-side by the item's returnable/cancelable quantity. Optional proof images via multipart images[].","query":"curl -X POST \\"https://your-domain.com/api/admin/rma/requests\\" \\\\\\n  -H \\"Authorization: Bearer <token>\\" \\\\\\n  -H \\"Content-Type: application/json\\" \\\\\\n  -d '{\\n    \\"order_id\\": 45,\\n    \\"order_item_id\\": 78,\\n    \\"rma_qty\\": 1,\\n    \\"resolution_type\\": \\"return\\",\\n    \\"rma_reason_id\\": 2,\\n    \\"information\\": \\"Customer reported a defect.\\",\\n    \\"package_condition\\": \\"opened\\"\\n  }'\\n","variables":"{\\n  \\"order_id\\": 45,\\n  \\"order_item_id\\": 78,\\n  \\"rma_qty\\": 1,\\n  \\"resolution_type\\": \\"return\\",\\n  \\"rma_reason_id\\": 2,\\n  \\"information\\": \\"Customer reported a defect.\\",\\n  \\"package_condition\\": \\"opened\\"\\n}\\n","response":"{\\n  \\"id\\": 12,\\n  \\"orderId\\": 45,\\n  \\"orderIncrementId\\": \\"000000045\\",\\n  \\"orderStatus\\": \\"processing\\",\\n  \\"customerName\\": \\"Jane Doe\\",\\n  \\"customerEmail\\": \\"jane@example.com\\",\\n  \\"isGuest\\": 0,\\n  \\"statusId\\": 1,\\n  \\"statusTitle\\": \\"Pending\\",\\n  \\"statusColor\\": \\"#FDB022\\",\\n  \\"packageCondition\\": \\"opened\\",\\n  \\"information\\": \\"Customer reported a defect.\\",\\n  \\"canReopen\\": false,\\n  \\"item\\": {\\n    \\"id\\": 30,\\n    \\"order_item_id\\": 78,\\n    \\"sku\\": \\"COASTALBREEZEMENSHOODIE\\",\\n    \\"name\\": \\"Coastal Breeze Men's Blue Zipper Hoodie\\",\\n    \\"quantity\\": 1,\\n    \\"resolution\\": \\"return\\",\\n    \\"reason_id\\": 2,\\n    \\"reason\\": \\"Damaged product\\",\\n    \\"variant_id\\": null\\n  },\\n  \\"images\\": [],\\n  \\"availableStatuses\\": [\\n    { \\"id\\": 2, \\"title\\": \\"Accept\\" },\\n    { \\"id\\": 3, \\"title\\": \\"Declined\\" }\\n  ],\\n  \\"messagesCount\\": 0,\\n  \\"createdAt\\": \\"2026-07-20T10:15:30+00:00\\",\\n  \\"updatedAt\\": \\"2026-07-20T10:15:30+00:00\\"\\n}\\n"}]},"headers":[],"relativePath":"api/rest-api/admin/sales/returns/create-return.md","filePath":"api/rest-api/admin/sales/returns/create-return.md"}`),d={name:"api/rest-api/admin/sales/returns/create-return.md"};function o(i,e,s,c,l,p){return n(),r("div",null,e[0]||(e[0]=[a('<h1 id="create-return" tabindex="-1">Create Return <a class="header-anchor" href="#create-return" aria-label="Permalink to &quot;Create Return&quot;">​</a></h1><p>Opens an RMA request for an order item. Use <a href="./list-returnable-items.html">List Returnable Items</a> to get the eligible items and their caps, and <a href="./list-return-reasons.html">List Return Reasons</a> for the reason ids of the chosen resolution type.</p><h2 id="endpoint" tabindex="-1">Endpoint <a class="header-anchor" href="#endpoint" aria-label="Permalink to &quot;Endpoint&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Endpoint</th><th>Method</th></tr></thead><tbody><tr><td><code>/api/admin/rma/requests</code></td><td>POST</td></tr></tbody></table><h2 id="request-body" tabindex="-1">Request Body <a class="header-anchor" href="#request-body" aria-label="Permalink to &quot;Request Body&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>order_id</code></td><td>integer</td><td>yes</td><td>The order to open the return against.</td></tr><tr><td><code>order_item_id</code></td><td>integer</td><td>yes</td><td>The order item being returned/canceled.</td></tr><tr><td><code>rma_qty</code></td><td>integer</td><td>yes</td><td>Quantity to return. Capped server-side by the item&#39;s returnable/cancelable quantity.</td></tr><tr><td><code>resolution_type</code></td><td>string</td><td>yes</td><td><code>return</code> or <code>cancel_items</code>.</td></tr><tr><td><code>rma_reason_id</code></td><td>integer</td><td>yes</td><td>A reason id valid for the chosen <code>resolution_type</code>.</td></tr><tr><td><code>information</code></td><td>string</td><td>no</td><td>Free-text note.</td></tr><tr><td><code>package_condition</code></td><td>string</td><td>no</td><td>Condition of the package (e.g. <code>opened</code>).</td></tr></tbody></table><p>To attach proof images, send the request as <code>multipart/form-data</code> with the fields above plus one or more <code>images[]</code> file parts.</p><h2 id="permission" tabindex="-1">Permission <a class="header-anchor" href="#permission" aria-label="Permalink to &quot;Permission&quot;">​</a></h2><p><code>sales.rma.requests.create</code></p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>See the <a href="/api/rest-api/admin/sales/returns/">Returns overview</a> for the status workflow.</p></div><p>All admin endpoints require an admin Bearer token — see <a href="/api/rest-api/admin/authentication.html">Authentication</a>.</p>',11)]))}const h=t(d,[["render",o]]);export{m as __pageData,h as default};
